// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

/// @title MockWETH
/// @notice Drop-in Wrapped-Ether for local Hardhat networks.
///         Implements the canonical WETH deposit/withdraw interface.
contract MockWETH is ERC20 {
    event Deposit(address indexed dst, uint256 wad);
    event Withdrawal(address indexed src, uint256 wad);

    constructor() ERC20("Wrapped Ether", "WETH") {}

    /// @notice Wrap ETH → WETH
    receive() external payable {
        deposit();
    }

    function deposit() public payable {
        _mint(msg.sender, msg.value);
        emit Deposit(msg.sender, msg.value);
    }

    /// @notice Unwrap WETH → ETH
    function withdraw(uint256 wad) external {
        require(balanceOf(msg.sender) >= wad, "MockWETH: INSUFFICIENT_BALANCE");
        _burn(msg.sender, wad);
        (bool ok, ) = msg.sender.call{value: wad}("");
        require(ok, "MockWETH: ETH_TRANSFER_FAILED");
        emit Withdrawal(msg.sender, wad);
    }

    function decimals() public pure override returns (uint8) {
        return 18;
    }
}

contracts/periphery/DEXLibrary.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../interfaces/IDEXPair.sol";
import "../interfaces/IDEXFactory.sol";

/// @title DEXLibrary
/// @notice Pure/view helper functions used by DEXRouter — quote prices, compute amounts, sort tokens.
library DEXLibrary {
    // ────────── Token helpers ──────────

    /// @notice Sort two tokens into (token0, token1) canonical order (token0 < token1)
    function sortTokens(address tokenA, address tokenB)
        internal
        pure
        returns (address token0, address token1)
    {
        require(tokenA != tokenB, "DEXLibrary: IDENTICAL_ADDRESSES");
        (token0, token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        require(token0 != address(0), "DEXLibrary: ZERO_ADDRESS");
    }

    /// @notice Compute the deterministic CREATE2 address for a pair without making any state reads
    function pairFor(address factory, address tokenA, address tokenB)
        internal
        view
        returns (address pair)
    {
        // Read from the factory directly — avoids hard-coding bytecode hashes
        pair = IDEXFactory(factory).getPair(tokenA, tokenB);
        require(pair != address(0), "DEXLibrary: PAIR_NOT_FOUND");
    }

    // ────────── Reserve helpers ──────────

    /// @notice Fetch the reserves for a pair, ordered so that reserveA corresponds to tokenA
    function getReserves(address factory, address tokenA, address tokenB)
        internal
        view
        returns (uint256 reserveA, uint256 reserveB)
    {
        (address token0, ) = sortTokens(tokenA, tokenB);
        address pair = IDEXFactory(factory).getPair(tokenA, tokenB);
        (uint256 reserve0, uint256 reserve1, ) = IDEXPair(pair).getReserves();
        (reserveA, reserveB) = tokenA == token0
            ? (reserve0, reserve1)
            : (reserve1, reserve0);
    }

    // ────────── Pricing ──────────

    /// @notice Given some amountA of tokenA and current reserves, return the equivalent amount of tokenB
    ///         (used when adding liquidity to maintain the current price ratio)
    function quote(uint256 amountA, uint256 reserveA, uint256 reserveB)
        internal
        pure
        returns (uint256 amountB)
    {
        require(amountA > 0, "DEXLibrary: INSUFFICIENT_AMOUNT");
        require(reserveA > 0 && reserveB > 0, "DEXLibrary: INSUFFICIENT_LIQUIDITY");
        amountB = (amountA * reserveB) / reserveA;
    }

    /// @notice Given an exact input amount and reserves, return the output amount (0.3% fee applied)
    function getAmountOut(uint256 amountIn, uint256 reserveIn, uint256 reserveOut)
        internal
        pure
        returns (uint256 amountOut)
    {
        require(amountIn > 0, "DEXLibrary: INSUFFICIENT_INPUT_AMOUNT");
        require(reserveIn > 0 && reserveOut > 0, "DEXLibrary: INSUFFICIENT_LIQUIDITY");
        uint256 amountInWithFee = amountIn * 997;
        uint256 numerator       = amountInWithFee * reserveOut;
        uint256 denominator     = reserveIn * 1000 + amountInWithFee;
        amountOut               = numerator / denominator;
    }

    /// @notice Given a desired exact output amount and reserves, return the required input amount (0.3% fee applied)
    function getAmountIn(uint256 amountOut, uint256 reserveIn, uint256 reserveOut)
        internal
        pure
        returns (uint256 amountIn)
    {
        require(amountOut > 0, "DEXLibrary: INSUFFICIENT_OUTPUT_AMOUNT");
        require(reserveIn > 0 && reserveOut > 0, "DEXLibrary: INSUFFICIENT_LIQUIDITY");
        uint256 numerator   = reserveIn * amountOut * 1000;
        uint256 denominator = (reserveOut - amountOut) * 997;
        amountIn            = numerator / denominator + 1;
    }

    // ────────── Multi-hop helpers ──────────

    /// @notice Given an exact input and a swap path, compute all intermediate and final output amounts
    function getAmountsOut(address factory, uint256 amountIn, address[] memory path)
        internal
        view
        returns (uint256[] memory amounts)
    {
        require(path.length >= 2, "DEXLibrary: INVALID_PATH");
        amounts = new uint256[](path.length);
        amounts[0] = amountIn;
        for (uint256 i; i < path.length - 1; i++) {
            (uint256 reserveIn, uint256 reserveOut) = getReserves(factory, path[i], path[i + 1]);
            amounts[i + 1] = getAmountOut(amounts[i], reserveIn, reserveOut);
        }
    }

    /// @notice Given a desired exact output and a swap path, compute all required input amounts
    function getAmountsIn(address factory, uint256 amountOut, address[] memory path)
        internal
        view
        returns (uint256[] memory amounts)
    {
        require(path.length >= 2, "DEXLibrary: INVALID_PATH");
        amounts = new uint256[](path.length);
        amounts[amounts.length - 1] = amountOut;
        for (uint256 i = path.length - 1; i > 0; i--) {
            (uint256 reserveIn, uint256 reserveOut) = getReserves(factory, path[i - 1], path[i]);
            amounts[i - 1] = getAmountIn(amounts[i], reserveIn, reserveOut);
        }
    }
}

contracts/periphery/DEXRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./DEXLibrary.sol";
import "../interfaces/IDEXFactory.sol";
import "../interfaces/IDEXPair.sol";
import "../interfaces/IWETH.sol";

/// @title DEXRouter
/// @notice The user-facing periphery contract.  All swap / liquidity operations
///         go through here.  Modelled after Uniswap V2 Router02.
contract DEXRouter {
    // ────────── Immutables ──────────
    address public immutable factory;
    address public immutable WETH;

    // ────────── Modifiers ──────────
    modifier ensure(uint256 deadline) {
        require(deadline >= block.timestamp, "DEXRouter: EXPIRED");
        _;
    }

    // ────────── Constructor ──────────
    constructor(address _factory, address _WETH) {
        factory = _factory;
        WETH    = _WETH;
    }

    // ────────── Receive ETH (from WETH.withdraw only) ──────────
    receive() external payable {
        assert(msg.sender == WETH);
    }

    // ══════════════════════════════════════════════════════════════
    //  LIQUIDITY
    // ══════════════════════════════════════════════════════════════

    /// @dev Shared add-liquidity logic.  Creates the pair if it doesn't exist yet.
    function _addLiquidity(
        address tokenA,
        address tokenB,
        uint256 amountADesired,
        uint256 amountBDesired,
        uint256 amountAMin,
        uint256 amountBMin
    ) internal returns (uint256 amountA, uint256 amountB) {
        // Create pair on first liquidity deposit
        if (IDEXFactory(factory).getPair(tokenA, tokenB) == address(0)) {
            IDEXFactory(factory).createPair(tokenA, tokenB);
        }
        (uint256 reserveA, uint256 reserveB) = DEXLibrary.getReserves(factory, tokenA, tokenB);
        if (reserveA == 0 && reserveB == 0) {
            (amountA, amountB) = (amountADesired, amountBDesired);
        } else {
            uint256 amountBOptimal = DEXLibrary.quote(amountADesired, reserveA, reserveB);
            if (amountBOptimal <= amountBDesired) {
                require(amountBOptimal >= amountBMin, "DEXRouter: INSUFFICIENT_B_AMOUNT");
                (amountA, amountB) = (amountADesired, amountBOptimal);
            } else {
                uint256 amountAOptimal = DEXLibrary.quote(amountBDesired, reserveB, reserveA);
                require(amountAOptimal <= amountADesired, "DEXRouter: EXCESSIVE_A_AMOUNT");
                require(amountAOptimal >= amountAMin, "DEXRouter: INSUFFICIENT_A_AMOUNT");
                (amountA, amountB) = (amountAOptimal, amountBDesired);
            }
        }
    }

    /// @notice Add liquidity for a token/token pair
    function addLiquidity(
        address tokenA,
        address tokenB,
        uint256 amountADesired,
        uint256 amountBDesired,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline
    )
        external
        ensure(deadline)
        returns (uint256 amountA, uint256 amountB, uint256 liquidity)
    {
        (amountA, amountB) = _addLiquidity(
            tokenA, tokenB, amountADesired, amountBDesired, amountAMin, amountBMin
        );
        address pair = IDEXFactory(factory).getPair(tokenA, tokenB);
        _safeTransferFrom(tokenA, msg.sender, pair, amountA);
        _safeTransferFrom(tokenB, msg.sender, pair, amountB);
        liquidity = IDEXPair(pair).mint(to);
    }

    /// @notice Add liquidity for a token/ETH pair — ETH is wrapped to WETH automatically
    function addLiquidityETH(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    )
        external
        payable
        ensure(deadline)
        returns (uint256 amountToken, uint256 amountETH, uint256 liquidity)
    {
        (amountToken, amountETH) = _addLiquidity(
            token, WETH, amountTokenDesired, msg.value, amountTokenMin, amountETHMin
        );
        address pair = IDEXFactory(factory).getPair(token, WETH);
        _safeTransferFrom(token, msg.sender, pair, amountToken);
        IWETH(WETH).deposit{value: amountETH}();
        assert(IWETH(WETH).transfer(pair, amountETH));
        liquidity = IDEXPair(pair).mint(to);
        // Refund excess ETH
        if (msg.value > amountETH) {
            (bool ok, ) = msg.sender.call{value: msg.value - amountETH}("");
            require(ok, "DEXRouter: ETH_REFUND_FAILED");
        }
    }

    /// @notice Remove liquidity from a token/token pair
    function removeLiquidity(
        address tokenA,
        address tokenB,
        uint256 liquidity,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline
    )
        public
        ensure(deadline)
        returns (uint256 amountA, uint256 amountB)
    {
        address pair = IDEXFactory(factory).getPair(tokenA, tokenB);
        IDEXPair(pair).transferFrom(msg.sender, pair, liquidity);
        (uint256 amount0, uint256 amount1) = IDEXPair(pair).burn(to);
        (address token0, ) = DEXLibrary.sortTokens(tokenA, tokenB);
        (amountA, amountB) = tokenA == token0
            ? (amount0, amount1)
            : (amount1, amount0);
        require(amountA >= amountAMin, "DEXRouter: INSUFFICIENT_A_AMOUNT");
        require(amountB >= amountBMin, "DEXRouter: INSUFFICIENT_B_AMOUNT");
    }

    /// @notice Remove liquidity from a token/ETH pair — WETH is unwrapped automatically
    function removeLiquidityETH(
        address token,
        uint256 liquidity,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    )
        public
        ensure(deadline)
        returns (uint256 amountToken, uint256 amountETH)
    {
        (amountToken, amountETH) = removeLiquidity(
            token,
            WETH,
            liquidity,
            amountTokenMin,
            amountETHMin,
            address(this),
            deadline
        );
        _safeTransfer(token, to, amountToken);
        IWETH(WETH).withdraw(amountETH);
        (bool ok, ) = to.call{value: amountETH}("");
        require(ok, "DEXRouter: ETH_TRANSFER_FAILED");
    }

    /// @notice Remove liquidity using a permit signature (gasless approval)
    function removeLiquidityWithPermit(
        address tokenA,
        address tokenB,
        uint256 liquidity,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline,
        bool approveMax,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external returns (uint256 amountA, uint256 amountB) {
        address pair = IDEXFactory(factory).getPair(tokenA, tokenB);
        uint256 value = approveMax ? type(uint256).max : liquidity;
        IDEXPair(pair).permit(msg.sender, address(this), value, deadline, v, r, s);
        (amountA, amountB) = removeLiquidity(tokenA, tokenB, liquidity, amountAMin, amountBMin, to, deadline);
    }

    /// @notice Remove liquidity from a token/ETH pair using a permit signature
    function removeLiquidityETHWithPermit(
        address token,
        uint256 liquidity,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline,
        bool approveMax,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external returns (uint256 amountToken, uint256 amountETH) {
        address pair = IDEXFactory(factory).getPair(token, WETH);
        uint256 value = approveMax ? type(uint256).max : liquidity;
        IDEXPair(pair).permit(msg.sender, address(this), value, deadline, v, r, s);
        (amountToken, amountETH) = removeLiquidityETH(
            token, liquidity, amountTokenMin, amountETHMin, to, deadline
        );
    }

    // ══════════════════════════════════════════════════════════════
    //  SWAP (exact-input)
    // ══════════════════════════════════════════════════════════════

    function _swap(uint256[] memory amounts, address[] memory path, address _to) internal {
        for (uint256 i; i < path.length - 1; i++) {
            (address input, address output) = (path[i], path[i + 1]);
            (address token0, )              = DEXLibrary.sortTokens(input, output);
            uint256 amountOut               = amounts[i + 1];
            (uint256 amount0Out, uint256 amount1Out) = input == token0
                ? (uint256(0), amountOut)
                : (amountOut, uint256(0));
            address to = i < path.length - 2
                ? IDEXFactory(factory).getPair(output, path[i + 2])
                : _to;
            IDEXPair(IDEXFactory(factory).getPair(input, output)).swap(
                amount0Out, amount1Out, to, new bytes(0)
            );
        }
    }

    /// @notice Swap exact tokens for tokens (multi-hop)
    function swapExactTokensForTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external ensure(deadline) returns (uint256[] memory amounts) {
        amounts = DEXLibrary.getAmountsOut(factory, amountIn, path);
        require(amounts[amounts.length - 1] >= amountOutMin, "DEXRouter: INSUFFICIENT_OUTPUT_AMOUNT");
        _safeTransferFrom(path[0], msg.sender, IDEXFactory(factory).getPair(path[0], path[1]), amounts[0]);
        _swap(amounts, path, to);
    }

    /// @notice Swap tokens for exact tokens (multi-hop)
    function swapTokensForExactTokens(
        uint256 amountOut,
        uint256 amountInMax,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external ensure(deadline) returns (uint256[] memory amounts) {
        amounts = DEXLibrary.getAmountsIn(factory, amountOut, path);
        require(amounts[0] <= amountInMax, "DEXRouter: EXCESSIVE_INPUT_AMOUNT");
        _safeTransferFrom(path[0], msg.sender, IDEXFactory(factory).getPair(path[0], path[1]), amounts[0]);
        _swap(amounts, path, to);
    }

    /// @notice Swap exact ETH for tokens
    function swapExactETHForTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable ensure(deadline) returns (uint256[] memory amounts) {
        require(path[0] == WETH, "DEXRouter: INVALID_PATH");
        amounts = DEXLibrary.getAmountsOut(factory, msg.value, path);
        require(amounts[amounts.length - 1] >= amountOutMin, "DEXRouter: INSUFFICIENT_OUTPUT_AMOUNT");
        IWETH(WETH).deposit{value: amounts[0]}();
        assert(IWETH(WETH).transfer(IDEXFactory(factory).getPair(path[0], path[1]), amounts[0]));
        _swap(amounts, path, to);
    }

    /// @notice Swap tokens for exact ETH
    function swapTokensForExactETH(
        uint256 amountOut,
        uint256 amountInMax,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external ensure(deadline) returns (uint256[] memory amounts) {
        require(path[path.length - 1] == WETH, "DEXRouter: INVALID_PATH");
        amounts = DEXLibrary.getAmountsIn(factory, amountOut, path);
        require(amounts[0] <= amountInMax, "DEXRouter: EXCESSIVE_INPUT_AMOUNT");
        _safeTransferFrom(path[0], msg.sender, IDEXFactory(factory).getPair(path[0], path[1]), amounts[0]);
        _swap(amounts, path, address(this));
        IWETH(WETH).withdraw(amounts[amounts.length - 1]);
        (bool ok, ) = to.call{value: amounts[amounts.length - 1]}("");
        require(ok, "DEXRouter: ETH_TRANSFER_FAILED");
    }

    /// @notice Swap exact tokens for ETH
    function swapExactTokensForETH(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external ensure(deadline) returns (uint256[] memory amounts) {
        require(path[path.length - 1] == WETH, "DEXRouter: INVALID_PATH");
        amounts = DEXLibrary.getAmountsOut(factory, amountIn, path);
        require(amounts[amounts.length - 1] >= amountOutMin, "DEXRouter: INSUFFICIENT_OUTPUT_AMOUNT");
        _safeTransferFrom(path[0], msg.sender, IDEXFactory(factory).getPair(path[0], path[1]), amounts[0]);
        _swap(amounts, path, address(this));
        IWETH(WETH).withdraw(amounts[amounts.length - 1]);
        (bool ok, ) = to.call{value: amounts[amounts.length - 1]}("");
        require(ok, "DEXRouter: ETH_TRANSFER_FAILED");
    }

    /// @notice Swap ETH for exact tokens
    function swapETHForExactTokens(
        uint256 amountOut,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable ensure(deadline) returns (uint256[] memory amounts) {
        require(path[0] == WETH, "DEXRouter: INVALID_PATH");
        amounts = DEXLibrary.getAmountsIn(factory, amountOut, path);
        require(amounts[0] <= msg.value, "DEXRouter: EXCESSIVE_INPUT_AMOUNT");
        IWETH(WETH).deposit{value: amounts[0]}();
        assert(IWETH(WETH).transfer(IDEXFactory(factory).getPair(path[0], path[1]), amounts[0]));
        _swap(amounts, path, to);
        // Refund excess ETH
        if (msg.value > amounts[0]) {
            (bool ok, ) = msg.sender.call{value: msg.value - amounts[0]}("");
            require(ok, "DEXRouter: ETH_REFUND_FAILED");
        }
    }

    // ══════════════════════════════════════════════════════════════
    //  VIEW HELPERS (delegate to DEXLibrary)
    // ══════════════════════════════════════════════════════════════

    function quote(uint256 amountA, uint256 reserveA, uint256 reserveB)
        external pure returns (uint256 amountB)
    {
        return DEXLibrary.quote(amountA, reserveA, reserveB);
    }

    function getAmountOut(uint256 amountIn, uint256 reserveIn, uint256 reserveOut)
        external pure returns (uint256 amountOut)
    {
        return DEXLibrary.getAmountOut(amountIn, reserveIn, reserveOut);
    }

    function getAmountIn(uint256 amountOut, uint256 reserveIn, uint256 reserveOut)
        external pure returns (uint256 amountIn)
    {
        return DEXLibrary.getAmountIn(amountOut, reserveIn, reserveOut);
    }

    function getAmountsOut(uint256 amountIn, address[] calldata path)
        external view returns (uint256[] memory amounts)
    {
        return DEXLibrary.getAmountsOut(factory, amountIn, path);
    }

    function getAmountsIn(uint256 amountOut, address[] calldata path)
        external view returns (uint256[] memory amounts)
    {
        return DEXLibrary.getAmountsIn(factory, amountOut, path);
    }

    // ══════════════════════════════════════════════════════════════
    //  PRIVATE TRANSFER HELPERS
    // ══════════════════════════════════════════════════════════════

    function _safeTransfer(address token, address to, uint256 value) private {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSignature("transfer(address,uint256)", to, value)
        );
        require(success && (data.length == 0 || abi.decode(data, (bool))), "DEXRouter: TRANSFER_FAILED");
    }

    function _safeTransferFrom(address token, address from, address to, uint256 value) private {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSignature("transferFrom(address,address,uint256)", from, to, value)
        );
        require(success && (data.length == 0 || abi.decode(data, (bool))), "DEXRouter: TRANSFER_FROM_FAILED");
    }
}

contracts/token/ERC20Template.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/// @title ERC20Template
/// @notice A simple ERC-20 token deployed by TokenFactory.
///         The deployer receives the full initial supply and becomes the owner.
contract ERC20Template is ERC20, Ownable {
    uint8 private _decimals;

    constructor(
        string memory tokenName,
        string memory tokenSymbol,
        uint8  tokenDecimals,
        uint256 initialSupply,
        address creator
    )
        ERC20(tokenName, tokenSymbol)
    {
        _decimals = tokenDecimals;
        _transferOwnership(creator);
        _mint(creator, initialSupply * (10 ** tokenDecimals));
    }

    function decimals() public view override returns (uint8) {
        return _decimals;
    }

    /// @notice Owner can mint additional tokens at any time
    function mint(address to, uint256 amount) external onlyOwner {
        _mint(to, amount);
    }

    /// @notice Anyone can burn their own tokens
    function burn(uint256 amount) external {
        _burn(msg.sender, amount);
    }
}

contracts/token/TokenFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./ERC20Template.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/// @title TokenFactory
/// @notice Allows anyone to launch a new ERC-20 token by paying a small creation fee.
///         The fee is forwarded to a configurable `feeReceiver` address.
contract TokenFactory is Ownable {
    // ────────── State ──────────
    uint256 public creationFee;
    address public feeReceiver;

    /// @notice All tokens ever deployed by this factory
    address[] public allTokens;

    /// @notice Tokens deployed by a given creator address
    mapping(address => address[]) public tokensByCreator;

    // ────────── Events ──────────
    event TokenCreated(
        address indexed token,
        address indexed creator,
        string  name,
        string  symbol,
        uint256 initialSupply
    );
    event FeeUpdated(uint256 newFee);
    event FeeReceiverUpdated(address newReceiver);

    // ────────── Constructor ──────────
    constructor(uint256 _creationFee, address _feeReceiver) {
        creationFee  = _creationFee;
        feeReceiver  = _feeReceiver;
    }

    // ────────── View ──────────
    function allTokensLength() external view returns (uint256) {
        return allTokens.length;
    }

    function tokensOfCreator(address creator) external view returns (address[] memory) {
        return tokensByCreator[creator];
    }

    // ────────── Mutative ──────────

    /// @notice Deploy a new ERC-20 token.  Caller must send at least `creationFee` ETH.
    /// @param tokenName     Human-readable name (e.g. "My Token")
    /// @param tokenSymbol   Ticker symbol (e.g. "MTK")
    /// @param tokenDecimals Decimals — typically 18
    /// @param initialSupply Number of whole tokens minted to the caller
    function createToken(
        string calldata tokenName,
        string calldata tokenSymbol,
        uint8           tokenDecimals,
        uint256         initialSupply
    ) external payable returns (address tokenAddress) {
        require(msg.value >= creationFee, "TokenFactory: INSUFFICIENT_FEE");
        require(bytes(tokenName).length   > 0, "TokenFactory: EMPTY_NAME");
        require(bytes(tokenSymbol).length > 0, "TokenFactory: EMPTY_SYMBOL");
        require(initialSupply > 0,             "TokenFactory: ZERO_SUPPLY");

        ERC20Template newToken = new ERC20Template(
            tokenName,
            tokenSymbol,
            tokenDecimals,
            initialSupply,
            msg.sender
        );
        tokenAddress = address(newToken);

        allTokens.push(tokenAddress);
        tokensByCreator[msg.sender].push(tokenAddress);

        // Forward creation fee to receiver
        if (creationFee > 0) {
            (bool ok, ) = feeReceiver.call{value: creationFee}("");
            require(ok, "TokenFactory: FEE_TRANSFER_FAILED");
        }

        // Refund any excess ETH
        uint256 excess = msg.value - creationFee;
        if (excess > 0) {
            (bool refundOk, ) = msg.sender.call{value: excess}("");
            require(refundOk, "TokenFactory: REFUND_FAILED");
        }

        emit TokenCreated(tokenAddress, msg.sender, tokenName, tokenSymbol, initialSupply);
    }

    // ────────── Admin ──────────
    function setCreationFee(uint256 _fee) external onlyOwner {
        creationFee = _fee;
        emit FeeUpdated(_fee);
    }

    function setFeeReceiver(address _receiver) external onlyOwner {
        require(_receiver != address(0), "TokenFactory: ZERO_ADDRESS");
        feeReceiver = _receiver;
        emit FeeReceiverUpdated(_receiver);
    }

    /// @notice Rescue any ETH accidentally sent directly to this contract
    function withdrawETH() external onlyOwner {
        (bool ok, ) = owner().call{value: address(this).balance}("");
        require(ok, "TokenFactory: WITHDRAW_FAILED");
    }
}
